public class ReportSummary { private long totalBooks,availableCopies,borrowedBooks,overdueBooks,totalMembers,totalTransactions; public long getTotalBooks(){return totalBooks;} public void setTotalBooks(long v){totalBooks=v;} public long getAvailableCopies(){return availableCopies;} public void setAvailableCopies(long v){availableCopies=v;} public long getBorrowedBooks(){return borrowedBooks;} public void setBorrowedBooks(long v){borrowedBooks=v;} public long getOverdueBooks(){return overdueBooks;} public void setOverdueBooks(long v){overdueBooks=v;} public long getTotalMembers(){return totalMembers;} public void setTotalMembers(long v){totalMembers=v;} public long getTotalTransactions(){return totalTransactions;} public void setTotalTransactions(long v){totalTransactions=v;} }
